output_text:
[
  {
    "id": "cart_first",
    "text": "A shopper is obliged to obtain a cart from the entrance cart station before doing the grocery run.",
    "abstraction": {
      "state_properties": {
        "atEntranceCartStation": {
          "and": [
            "at(1,5)",
            "cartAt(1,5)"
          ]
        },
        "withCart": "hasCart"
      },
      "events": {
        "acquireEntranceCart": {
          "pre": {
            "and": [
              "atEntranceCartStation",
              "PICKUP_CART"
            ]
          },
          "post": "withCart"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "START",
      "discharge": "acquireEntranceCart"
    }
  },
  {
    "id": "items_only_with_cart",
    "text": "A shopper is prohibited from picking up shelf items unless they currently have a cart.",
    "abstraction": {
      "state_properties": {
        "withoutCart": {
          "not": "hasCart"
        }
      },
      "events": {
        "cartlessItemPickup": {
          "pre": {
            "and": [
              "PICKUP_ITEM",
              "withoutCart"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "cartlessItemPickup"
    }
  },
  {
    "id": "no_hand_carrying_goods",
    "text": "A shopper is prohibited from carrying grocery items by hand inside the store.",
    "abstraction": {
      "state_properties": {
        "carryingItemByHand": "handFull"
      },
      "events": {
        "itemTakenIntoHand": {
          "pre": "PICKUP_ITEM",
          "post": "carryingItemByHand"
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "carryingItemByHand"
    }
  },
  {
    "id": "return_loaded_cart_to_bay",
    "text": "After placing any item in a cart, the shopper is obliged to return the cart to the cart-return bay before leaving.",
    "abstraction": {
      "state_properties": {
        "atCartReturnBay": "at(0,1)",
        "cartParkedAtReturnBay": "cartAt(0,1)",
        "withCart": "hasCart"
      },
      "events": {
        "itemLoadedIntoCart": {
          "pre": {
            "and": [
              "PICKUP_ITEM",
              "withCart"
            ]
          },
          "post": "withCart"
        },
        "returnCartToBay": {
          "pre": {
            "and": [
              "LEAVE_CART",
              "withCart",
              "atCartReturnBay"
            ]
          },
          "post": "cartParkedAtReturnBay"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "itemLoadedIntoCart",
      "discharge": "returnCartToBay"
    }
  },
  {
    "id": "leave_cart_only_at_bay",
    "text": "A shopper is prohibited from putting down a cart anywhere except the designated cart-return bay.",
    "abstraction": {
      "state_properties": {
        "atCartReturnBay": "at(0,1)",
        "outsideCartReturnBay": {
          "not": "atCartReturnBay"
        }
      },
      "events": {
        "abandonCartOutsideBay": {
          "pre": {
            "and": [
              "LEAVE_CART",
              "outsideCartReturnBay"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "abandonCartOutsideBay"
    }
  },
  {
    "id": "cartless_exit",
    "text": "A shopper is prohibited from exiting the supermarket while still holding or pushing a cart.",
    "abstraction": {
      "state_properties": {
        "withCart": "hasCart"
      },
      "events": {
        "exitWithCart": {
          "pre": {
            "and": [
              "EXIT",
              "withCart"
            ]
          },
          "post": null
        },
        "exitWithoutCart": {
          "pre": {
            "and": [
              "EXIT",
              {
                "not": "withCart"
              }
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "exitWithCart"
    }
  },
  {
    "id": "no_cart_east_in_exit_aisle",
    "text": "A shopper is prohibited from pushing a cart eastward along the bottom exit aisle.",
    "abstraction": {
      "state_properties": {
        "bottomExitAisle": {
          "or": [
            "at(0,5)",
            "at(1,5)",
            "at(2,5)",
            "at(3,5)",
            "at(4,5)",
            "at(5,5)",
            "at(6,5)",
            "at(7,5)",
            "at(8,5)"
          ]
        },
        "withCart": "hasCart"
      },
      "events": {
        "pushCartEastInExitAisle": {
          "pre": {
            "and": [
              "E",
              "withCart",
              "bottomExitAisle"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "pushCartEastInExitAisle"
    }
  },
  {
    "id": "do_not_reclaim_returned_cart",
    "text": "Once a cart has been parked at the cart-return bay, shoppers are prohibited from picking that returned cart back up.",
    "abstraction": {
      "state_properties": {
        "atCartReturnBay": "at(0,1)",
        "cartParkedAtReturnBay": "cartAt(0,1)"
      },
      "events": {
        "reclaimReturnedCart": {
          "pre": {
            "and": [
              "PICKUP_CART",
              "atCartReturnBay",
              "cartParkedAtReturnBay"
            ]
          },
          "post": "hasCart"
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "reclaimReturnedCart"
    }
  }
]
